python3 -c "
import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_1/projects/struct_self_consist_ie/logs/workers/worker_review_r9_data_integrity_20260516T010154_result.json') as f:
    data = json.load(f)
raw = data.get('raw', '')

# Find all thinking blocks that mention findings, discrepancy, mismatch, etc.
findings = []
for line in raw.split('\n'):
    line = line.strip()
    if not line:
        continue
    try:
        obj = json.loads(line)
        if obj.get('type') == 'assistant':
            msg = obj.get('message', {})
            content = msg.get('content', [])
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type') == 'thinking':
                        thinking = c.get('thinking', '')
                        # Look for key findings
                        for keyword in ['mismatch', 'discrepancy', 'CRITICAL', 'WARNING', 'wrong', 'incorrect', 'bug', 'inconsisten', 'verified', 'matches', 'Table 1', 'Table 2', 'Table 3', 'Table 4', 'audit']:
                            if keyword.lower() in thinking.lower():
                                # Extract a snippet around the keyword
                                idx = thinking.lower().find(keyword.lower())
                                start = max(0, idx - 100)
                                end = min(len(thinking), idx + 200)
                                snippet = thinking[start:end]
                                findings.append((keyword, snippet))
                                break
    except:
        pass

# Print unique findings (deduplicated by snippet)
seen = set()
print(f'Total findings: {len(findings)}')
for kw, snippet in findings[-30:]:
    key = snippet[:50]
    if key not in seen:
        seen.add(key)
        print(f'\\n[{kw}]: ...{snippet}...')
" 2>&1 | head -200

